/* ============================================================
   أطياب الجاسم (React) — عروض المنتجات (ProductOffers)

   كل عرض = شاشة كاملة: صورة العرض + عنوان العرض + مدّة العرض
   (عدّاد تنازلي من expiresAt) + اسم المناسبة وتاريخها + العنوان
   الداعم (tagline) + قصة العرض + المزايا + السعر + السعر القديم +
   نسبة الخصم + مبلغ التوفير + القطع المتبقية + كود العرض بزر نسخ +
   زرّ «أضف الباقة للسلة» ورابط «تفاصيل المنتج».

   ★ المصدر الوحيد: GET /api/offers/all عبر شريحة offers (Redux) —
     بلا أي بيانات ثابتة. الحالات: تحميل ← OfferSkeleton،
     فشل ← رسالة + إعادة المحاولة، فراغ ← رسالة نصية.
   ★ يُستدعى من OfferPage داخل #offersView (كل أنماط .of-* محصورة به).
   ============================================================ */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { partsOf, unitName, pad2, rgbOf, useMoney } from "../../redux/selectors.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { getOffers, selectOffersList, selectOffersStatus, selectOffersError } from "../../redux/slices/offersSlice.js";
import { addItem } from "../../redux/slices/cartSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { Link } from "react-router-dom";
import { productPath } from "../../routes.js";
import { Money } from "../Source/Money.jsx";
import { Icon, ProductImage } from "../Source/Icons.jsx";
import { OfferSkeleton } from "../Skeletons/index.js";
import { useOffersTilt } from "./offersTilt.js";
import { flyFromButton } from "../../utils/flyToCart.js";
import { toUserMessage } from "../../api/friendlyError.js";

const ORDERS = { full: ["d", "h", "m", "s"], short: ["h", "m", "s"] };

function Countdown(props) {
  const rec = props.rec;
  const language = props.language;
  /* ★ ينبض وحده: إعادة رسم الأب كل ثانية كانت تخنق الإطارات
     فيطفي حارس الأداء محرك الـ3D — الآن الأب ثابت والثانية وحدها تتحرك */
  const [now, setNow] = useState(function () {
    return Date.now();
  });
  useEffect(
    function () {
      const id = window.setInterval(function () {
        setNow(Date.now());
      }, 1000);
      return function () {
        window.clearInterval(id);
      };
    },
    []
  );
  const rem = Math.max(0, rec.end - now);
  const t = partsOf(rem);
  const order = t.d > 0 ? ORDERS.full : ORDERS.short;
  const span = rec.end - rec.start;
  const elapsed = span > 0 ? Math.max(0, Math.min(1, (now - rec.start) / span)) : 0;

  return (
    <div className="of-cd">
      <span className="of-cd-head">
        <Icon name="clock" strokeWidth={1.8} />
        <span>{language === "en" ? "Offer ends in" : "ينتهي العرض خلال"}</span>
      </span>
      <div className="of-cd-units">
        {order.map(function (kind) {
          return (
            <span className="of-cd-unit" data-kind={kind} key={kind}>
              <b key={kind === "s" ? t.s : kind} className={kind === "s" ? "is-tick" : undefined}>{pad2(t[kind])}</b>
              <i>{unitName(kind, t[kind], language)}</i>
            </span>
          );
        })}
      </div>
      <span className="of-cd-bar" aria-hidden="true">
        <i style={{ width: (elapsed * 100).toFixed(1) + "%" }} />
      </span>
    </div>
  );
}

/* نص ثنائي اللغة من حقول العرض */
function pickLang(ar, en, language) {
  if (language === "en") return en || ar || "";
  return ar || en || "";
}

function kindNounOf(typeId, language) {
  const t = Number(typeId);
  if (t === 2) return language === "en" ? "Bakhoor" : "بخور";
  if (t === 3) return language === "en" ? "Oud" : "عود";
  if (t === 4) return language === "en" ? "Body mist" : "معطّر جسم";
  return language === "en" ? "Perfume" : "عطر";
}

export default function ProductOffers() {
  const dispatch = useAppDispatch();
  const money = useMoney();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const offers = useAppSelector(selectOffersList);
  const status = useAppSelector(selectOffersStatus);
  const loadError = useAppSelector(selectOffersError);

  /* ★ الجلب من الخادم الحي مرة واحدة (الشريحة تمنع التكرار) */
  useEffect(
    function () {
      dispatch(getOffers());
    },
    [dispatch]
  );

  const slides = useMemo(
    function () {
      const now = Date.now();
      return (offers || [])
        .filter(function (o) {
          if (!o || o.isActive === false || o.isRunning === false) return false;
          const end = Date.parse(o.expiresAt) || 0;
          return !end || end > now;
        })
        .sort(function (a, b) {
          return Number(a.sortOrder) - Number(b.sortOrder);
        })
        .map(function (o) {
          const start = Date.parse(o.startsAt) || now;
          let end = Date.parse(o.expiresAt) || 0;
          if (!end) end = start + 72 * 3600e3;
          return { offer: o, rec: { key: String(o.id), start: start, end: end, mode: "server" } };
        });
    },
    [offers]
  );

  const [live, setLive] = useState([]);
  const [active, setActive] = useState(0);
  const listRef = useRef(null);

  /* كشف كل شاشة عند اقترابها (نفس منطق الديمو: قياس مباشر +
     مراقب بحدّ صفر + تمرير/مقاس كاحتياط + حماية أخيرة) */
  useEffect(
    function () {
      const root = listRef.current;
      if (!root) return undefined;
      const items = Array.prototype.slice.call(root.querySelectorAll(".of-slide"));
      if (!items.length) return undefined;

      function mark(el) {
        const index = Number(el.getAttribute("data-index"));
        if (isNaN(index)) return;
        setLive(function (prev) {
          return prev.indexOf(index) === -1 ? prev.concat([index]) : prev;
        });
      }

      function sync() {
        const vh = window.innerHeight || document.documentElement.clientHeight || 800;
        const pad = Math.min(140, vh * 0.22);
        let best = -1;
        let bestDist = Infinity;
        for (let i = 0; i < items.length; i++) {
          const rect = items[i].getBoundingClientRect();
          if (!rect.height) continue;
          if (rect.top < vh - pad * 0.35 && rect.bottom > pad * 0.35) mark(items[i]);
          const dist = Math.abs((rect.top + rect.bottom) / 2 - vh / 2);
          if (dist < bestDist) {
            bestDist = dist;
            best = i;
          }
        }
        if (best >= 0) setActive(best);
      }

      let raf = 0;
      function schedule() {
        if (raf) return;
        raf = window.requestAnimationFrame(function () {
          raf = 0;
          sync();
        });
      }

      function failsafe() {
        const vh = window.innerHeight || document.documentElement.clientHeight || 800;
        for (let i = 0; i < items.length; i++) {
          const rect = items[i].getBoundingClientRect();
          if (rect.bottom > 0 && rect.top < vh) mark(items[i]);
        }
      }

      schedule();
      const t1 = window.setTimeout(sync, 150);
      const t2 = window.setTimeout(sync, 700);
      const t3 = window.setTimeout(failsafe, 1500);

      function onShow() {
        schedule();
        failsafe();
      }

      window.addEventListener("scroll", schedule, { passive: true, capture: true });
      window.addEventListener("resize", schedule);
      window.addEventListener("pageshow", onShow);
      document.addEventListener("visibilitychange", onShow);
      const ro = window.ResizeObserver ? new ResizeObserver(schedule) : null;
      if (ro) ro.observe(root);

      let io = null;
      if ("IntersectionObserver" in window) {
        io = new IntersectionObserver(
          function (entries) {
            entries.forEach(function (entry) {
              if (entry.isIntersecting) mark(entry.target);
            });
          },
          { threshold: 0, rootMargin: "0px 0px -6% 0px" }
        );
        items.forEach(function (el) {
          io.observe(el);
        });
      }

      return function () {
        if (raf) window.cancelAnimationFrame(raf);
        window.clearTimeout(t1);
        window.clearTimeout(t2);
        window.clearTimeout(t3);
        window.removeEventListener("scroll", schedule, { capture: true });
        window.removeEventListener("resize", schedule);
        window.removeEventListener("pageshow", onShow);
        document.removeEventListener("visibilitychange", onShow);
        if (ro) ro.disconnect();
        if (io) io.disconnect();
      };
    },
    [slides.length]
  );

  /* ★ محرك البهجة: طيّ الدفتر + ميل المؤشر + لمعة الزجاج (يعمل بعد بناء الشرائح) */
  useOffersTilt(slides.length);

  const goTo = useCallback(function (index) {
    const root = listRef.current;
    if (!root) return;
    const el = root.querySelector('.of-slide[data-index="' + index + '"]');
    if (!el) return;
    try {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    } catch (e) {
      el.scrollIntoView();
    }
  }, []);

  function copyCode(code) {
    if (!code) return;
    const done = function (ok) {
      dispatch(uiActions.toastShown(ok ? (language === "en" ? "Code copied: " + code : "تم نسخ الكود " + code) : (language === "en" ? "Copy manually: " + code : "انسخ الكود يدوياً: " + code)));
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(code).then(
        function () {
          done(true);
        },
        function () {
          done(false);
        }
      );
      return;
    }
    done(false);
  }

  function addBundle(offer, btn) {
    /* ★ حارس النقرة المزدوجة (كزر السلة): الباقة تُضاف مرة واحدة مهما
       تكررت الضغطات خلال 800ms — كان النقر المزدوج يضاعف القطع ويُربك عدّاد الشارة. */
    const at = Date.now();
    if (at - (addBundle.last || 0) < 800) return;
    addBundle.last = at;
    /* ★ R9: صورة العرض تطير إلى العربة */
    try {
      flyFromButton(btn || null, "cart");
    } catch (e) {}
    /* ★ الباقة ليست منتجاً عند الخادم (§3: معرّف 9000000+ مخترع محلياً
       يردّ عليه POST /items بـ404): تُفكّ إلى مكوّناتها الحقيقية
       (productId من §2) قطعة واحدة لكل مكوّن — فيقبلها الخادم. */
    const seen = {};
    let n = 0;
    (offer.items || []).forEach(function (it) {
      const id = Number(it.id);
      if (!id || id >= 9000000 || seen[id]) return;
      seen[id] = true;
      n += 1;
      /* ★ البند 6: تُوسم القطعة بباقتها — للتسعير الخلفي (quote+إنشاء) */
      dispatch(addItem(id, 1, offer.id));
    });
    dispatch(
      uiActions.toastShown(
        n > 0
          ? language === "en"
            ? "Bundle expanded into " + n + " product(s) in your cart"
            : "فُكّت الباقة إلى " + n + " منتج في عربتك (بمعرّفات الخادم)"
          : language === "en"
            ? "This bundle has no server products"
            : "هذه الباقة بلا منتجات معروفة عند الخادم"
      )
    );
  }

  /* ---------- حالات Redux التفاعلية ---------- */
  if ((status === "loading" || status === "idle") && !offers.length) {
    return <OfferSkeleton count={2} />;
  }

  if (status === "failed" && !offers.length) {
    return (
      <div className="of-empty" role="alert">
        <p>{toUserMessage(loadError, language === "en" ? "en" : "ar") || (language === "en" ? "Could not load offers." : "تعذّر جلب العروض.")}</p>
        <button
          className="btn-primary"
          type="button"
          onClick={function () {
            dispatch(getOffers(true));
          }}
        >
          {language === "en" ? "Retry" : "إعادة المحاولة"}
        </button>
      </div>
    );
  }

  if (!slides.length) {
    return (
      <div className="of-empty" role="status">
        <p>{language === "en" ? "No offers right now." : "لا توجد عروض حالياً."}</p>
      </div>
    );
  }

  return (
    <div ref={listRef}>
      <nav className="of-rail" aria-label={language === "en" ? "Browse offers" : "التنقّل بين العروض"}>
        <span className="of-rail-track" aria-hidden="true">
          <i style={{ height: ((active + 1) / slides.length) * 100 + "%" }} />
        </span>
        {slides.map(function (entry, i) {
          const title = pickLang(entry.offer.nameAr, entry.offer.nameEn, language) || entry.offer.name;
          return (
            <button
              className={"of-dot" + (i === active ? " is-active" : "")}
              type="button"
              key={entry.offer.id || entry.offer.key}
              aria-label={title + " — " + (language === "en" ? "offer " : "عرض ") + (i + 1) + " / " + slides.length}
              aria-current={i === active ? "true" : "false"}
              onClick={function () {
                goTo(i);
              }}
            >
              <i aria-hidden="true" />
              <span>{title}</span>
            </button>
          );
        })}
        <span className="of-rail-count" aria-hidden="true">
          {active + 1} / {slides.length}
        </span>
      </nav>

      {slides.map(function (entry, index) {
        const offer = entry.offer;
        const items = offer.items || [];
        const first = items[0] || null;
        const offerName = pickLang(offer.nameAr, offer.nameEn, language) || offer.name;
        const occasion = pickLang(offer.occasionAr, offer.occasionEn, language);
        const dateLabel = pickLang(offer.dateLabelAr, offer.dateLabelEn, language);
        const tagline = pickLang(offer.taglineAr, offer.taglineEn, language);
        const story = pickLang(offer.storyAr, offer.storyEn, language);
        const perks = language === "en" ? offer.perksEn : offer.perksAr;
        const names = items.map(function (it) {
          return pickLang(it.nameAr, it.nameEn, language);
        }).filter(Boolean);
        const kicker = names.length > 2
          ? names[0] + " +" + (names.length - 1)
          : names.join(" + ");
        const kindNoun = first ? kindNounOf(first.typeId, language) : (language === "en" ? "Bundle" : "باقة");

        const itemsBefore = items.reduce(function (s, it) {
          return s + (Number(it.price) || 0);
        }, 0);
        const itemsFinal = items.reduce(function (s, it) {
          return s + (Number(it.finalPrice) || Number(it.price) || 0);
        }, 0);
        /* ★ الـ API يرجع سعر العرض 0 أحياناً — نحسبه من مجموع محتوياته */
        const before = Number(offer.priceBefore) || itemsBefore;
        const price = Number(offer.finalPrice) || itemsFinal || before;
        const hasPrice = price > 0;
        let pct = 0;
        if (String(offer.discountType).toLowerCase().indexOf("percent") === 0) pct = Math.round(Number(offer.discountValue) || 0);
        else if (before > price && before > 0) pct = Math.round(((before - price) / before) * 100);
        const save = Math.max(0, before - price);

        return (
          <article
            className={"of-slide" + (live.indexOf(index) !== -1 ? " is-live" : "")}
            data-key={offer.key}
            data-index={index}
            data-motif={offer.motif || ""}
            key={offer.id || offer.key}
            style={{
              "--of-a": offer.accent || "#157347",
              "--of-a-rgb": rgbOf(offer.accent),
              "--of-b": offer.accent2 || "#e6c470",
              "--of-b-rgb": rgbOf(offer.accent2)
            }}
          >
            <span className="of-glow" aria-hidden="true" />

            <div className="of-inner">
              <div className="of-copy">
                <div className="of-head">
                  <div className="of-headings">
                    <p className="of-kicker">
                      {kicker} · {kindNoun}
                    </p>
                    <h2 className="of-title">{offerName}</h2>
                    {occasion || dateLabel ? (
                      <p className="of-occasion">
                        <span className="of-occasion-name">{occasion}</span>
                        {occasion && dateLabel ? <span className="of-sep">·</span> : null}
                        <span className="of-occasion-date">{dateLabel}</span>
                      </p>
                    ) : null}
                  </div>
                </div>

                {tagline ? <p className="of-tagline">{tagline}</p> : null}
                {story ? <p className="of-story">{story}</p> : null}

                {items.length > 1 ? (
                  <p className="of-contents">
                    <Icon name="gift" strokeWidth={1.8} />
                    <span>
                      {language === "en" ? "Bundle includes: " : "محتويات الباقة: "}
                      {names.join(" + ")}
                    </span>
                  </p>
                ) : null}

                {perks && perks.length ? (
                  <ul className="of-perks">
                    {perks.map(function (perk, i) {
                      return (
                        <li key={i}>
                          <Icon name="check" strokeWidth={2.2} />
                          <span>{perk}</span>
                        </li>
                      );
                    })}
                  </ul>
                ) : null}

                {hasPrice ? (
                <div className="of-price">
                  <span className="of-price-main">
                    <b className="of-num">{money.amount(price)}</b>
                    <small className="of-cur">{money.symbol}</small>
                    {before > price ? (
                      <s className="of-was">
                        <Money sar={before} />
                      </s>
                    ) : null}
                  </span>
                  <span className="of-price-meta">
                    {pct > 0 ? <span className="of-off">{language === "en" ? pct + "% OFF" : "خصم " + pct + "%"}</span> : null}
                    {save > 0 ? (
                      <span className="of-save">
                        {language === "en" ? "Save " : "توفير "}<Money sar={save} />
                      </span>
                    ) : null}
                  </span>
                </div>
                ) : null}

                <div className="of-actions">
                  {items.length ? (
                    <button
                      className="of-add"
                      type="button"
                      onClick={function (e) {
                        addBundle(offer, e.currentTarget);
                      }}
                    >
                      <Icon name="cart" strokeWidth={1.9} />
                      <span>{language === "en" ? "Add bundle to cart" : "أضف الباقة للسلة"}</span>
                    </button>
                  ) : null}
                  {first ? (
                    <Link className="of-more" to={productPath(first.id)}>
                      <span>{language === "en" ? "Product details" : "تفاصيل المنتج"}</span>
                      <Icon name="back" strokeWidth={2} />
                    </Link>
                  ) : null}
                </div>

                <p className="of-foot">
                  {Number(offer.stockLeft) > 0 ? (
                    <span className="of-stock">
                      <b>{offer.stockLeft}</b> {language === "en" ? "pieces left at this price" : "قطعة فقط بهذا السعر"}
                    </span>
                  ) : null}
                  {offer.code ? (
                    <span className="of-code">
                      {language === "en" ? "Code " : "الكود "}<b>{offer.code}</b>
                    </span>
                  ) : null}
                  {offer.code ? (
                    <button
                      className="of-copybtn"
                      type="button"
                      onClick={function () {
                        copyCode(offer.code);
                      }}
                    >
                      <Icon name="copy" strokeWidth={1.7} />
                      <span>{language === "en" ? "Copy" : "نسخ"}</span>
                    </button>
                  ) : null}
                </p>
              </div>

              <div className="of-media">
                <div className="of-stage">
                  <Countdown rec={entry.rec} language={language} />
                  <figure className="of-frame">
                    {first ? (
                      <Link to={productPath(first.id)} aria-label={offerName}>
                        <ProductImage product={{ image: offer.mainImageUrl, name: offerName }} alt={offerName} eager />
                      </Link>
                    ) : (
                      <ProductImage product={{ image: offer.mainImageUrl, name: offerName }} alt={offerName} eager />
                    )}
                  </figure>
                </div>
              </div>
            </div>
          </article>
        );
      })}
    </div>
  );
}
