/* ============================================================
   أطياب الجاسم (React) — محرّك الحركة ثلاثية الأبعاد للعروض
   (نقل حرفي لمنطق src/offers-3d.js من الديمو إلى خطّاف React)

   يفعل ثلاثة أشياء على الشريحة النشطة داخل #offersView:
     1) يكتب --of-c لموضع كل شريحة عن منتصف الشاشة (طيّ الدفتر).
     2) ميل --of-rx/--of-ry يتبع المؤشّر (أو الجيرسكوب أو موجة هادئة).
     3) لمعة --of-mx/--of-my/--of-sheen على زجاج الصورة.
   مع حماية أداء (تخفيف ثم إيقاف تحت ~38fps) واحترام تقليل الحركة.
   بلا السكربت تبقى القيم صفراً والصفحة ثابتة — لا اعتماد عليه.
   ============================================================ */

import { useEffect } from "react";

function clamp(v, a, b) {
  return v < a ? a : v > b ? b : v;
}

function headerHeight() {
  let h = 0;
  const el = document.querySelector("header.site, header");
  if (el) {
    const r = el.getBoundingClientRect();
    if (r.height) h = r.height;
  }
  if (!h) {
    const v = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--header-h"));
    h = isFinite(v) && v > 0 ? v : 70;
  }
  return h;
}

function nowMs() {
  try {
    return performance.now();
  } catch (e) {
    return Date.now();
  }
}

export function useOffersTilt(count) {
  useEffect(
    function () {
      if (!count) return undefined;
      const view = document.getElementById("offersView");
      if (!view) return undefined;
      let reduce = false;
      let fine = false;
      try {
        const mq = window.matchMedia;
        reduce = !!(mq && mq("(prefers-reduced-motion: reduce)").matches);
        fine = !!(mq && mq("(hover: hover) and (pointer: fine)").matches);
      } catch (e) {}
      if (reduce) return undefined;

      const slides = Array.prototype.slice.call(view.querySelectorAll(".of-slide"));
      if (!slides.length) return undefined;

      let active = null;
      let rafId = 0;
      let running = true;
      let quality = 2;
      const ptr = { x: 0, y: 0, tx: 0, ty: 0, px: 0, py: 0, seen: 0, live: false };
      const tilt = { x: 0, y: 0 };
      const sheen = { x: 50, y: 42, on: false };
      let fpsFrames = 0;
      let fpsSum = 0;
      let lastTs = 0;
      const shownAt = nowMs();
      const MIN_FPS = 38;
      const IDLE_MS = 2200;

      function frame(ts) {
        if (!running) return;
        rafId = window.requestAnimationFrame(frame);

        const vh = window.innerHeight || 800;
        const head = headerHeight();
        const mid = head + (vh - head) / 2;
        const span = Math.max(1, (vh - head) * 0.72);

        let best = Infinity;
        let bestIndex = -1;
        for (let i = 0; i < slides.length; i++) {
          const el = slides[i];
          const r = el.getBoundingClientRect();
          const c = clamp((r.top + r.height / 2 - mid) / span, -1, 1);
          el.style.setProperty("--of-c", c.toFixed(4));
          const d = Math.abs(c);
          if (d < best) {
            best = d;
            bestIndex = i;
          }
        }

        const nextActive = bestIndex >= 0 ? slides[bestIndex] : null;
        if (nextActive !== active) {
          if (active) {
            active.style.setProperty("--of-rx", "0deg");
            active.style.setProperty("--of-ry", "0deg");
            active.style.setProperty("--of-sheen", "0");
          }
          active = nextActive;
          tilt.x = tilt.y = 0;
          ptr.x = ptr.y = ptr.tx = ptr.ty = 0;
        }
        if (!active) return;

        const now = ts || Date.now();
        const idle = now - ptr.seen > IDLE_MS;
        let trx;
        let try_;
        if (!idle && ptr.live) {
          trx = clamp(-ptr.y * 9.5, -11, 11);
          try_ = clamp(ptr.x * 12.5, -13, 13);
        } else if (!idle && !ptr.live && quality > 0) {
          trx = 0;
          try_ = 0;
        } else {
          trx = Math.cos(now / 6100) * 1.5;
          try_ = Math.sin(now / 4900) * 2.4;
        }

        const k = quality > 1 ? 0.09 : 0.2;
        tilt.x += (trx - tilt.x) * k;
        tilt.y += (try_ - tilt.y) * k;
        active.style.setProperty("--of-rx", tilt.x.toFixed(3) + "deg");
        active.style.setProperty("--of-ry", tilt.y.toFixed(3) + "deg");

        if (quality > 1 && fine) {
          const wantOn = ptr.live && !idle;
          const frameEl = active.querySelector(".of-frame");
          if (wantOn && frameEl) {
            const fr = frameEl.getBoundingClientRect();
            if (fr.width > 0) {
              sheen.x = clamp((ptr.px - fr.left) / fr.width, 0, 1) * 100;
              sheen.y = clamp((ptr.py - fr.top) / fr.height, 0, 1) * 100;
            }
          }
          const on = wantOn ? 1 : 0;
          if (on !== (sheen.on ? 1 : 0) || on) {
            active.style.setProperty("--of-mx", (on ? sheen.x : 50).toFixed(2) + "%");
            active.style.setProperty("--of-my", (on ? sheen.y : 42).toFixed(2) + "%");
            active.style.setProperty("--of-sheen", on ? "1" : "0");
            sheen.on = !!on;
          }
        } else if (sheen.on) {
          active.style.setProperty("--of-sheen", "0");
          sheen.on = false;
        }

        if (lastTs) {
          const dt = now - lastTs;
          if (dt > 0 && dt < 500) {
            fpsSum += dt;
            fpsFrames++;
          }
        }
        lastTs = now;

        if (fpsFrames >= 90) {
          const avg = fpsSum / fpsFrames;
          fpsFrames = 0;
          fpsSum = 0;
          if (avg > 1000 / MIN_FPS) {
            if (quality === 2) {
              quality = 1;
              sheen.on = false;
              if (active) active.style.setProperty("--of-sheen", "0");
            } else if (quality === 1 && now - shownAt > 1500) {
              stop(true);
            }
          }
        }
      }

      function onPointer(e) {
        if (!fine) return;
        ptr.px = e.clientX;
        ptr.py = e.clientY;
        ptr.tx = clamp((e.clientX / (window.innerWidth || 1) - 0.5) * 2, -1, 1);
        ptr.ty = clamp((e.clientY / (window.innerHeight || 1) - 0.5) * 2, -1, 1);
        ptr.x = ptr.tx;
        ptr.y = ptr.ty;
        ptr.live = true;
        ptr.seen = nowMs();
      }

      function onLeave() {
        ptr.live = false;
        ptr.seen = 0;
      }

      function onOrient(e) {
        if (e.gamma === null || e.gamma === undefined) return;
        const g = clamp((e.gamma || 0) / 26, -1, 1);
        const b = clamp(((e.beta || 0) - 40) / 26, -1, 1);
        ptr.tx = g;
        ptr.ty = b;
        ptr.x = g;
        ptr.y = b;
        ptr.live = false;
        ptr.seen = nowMs();
      }

      function stop(killed) {
        running = false;
        if (rafId) {
          window.cancelAnimationFrame(rafId);
          rafId = 0;
        }
        view.classList.remove("of3d-on");
        if (killed) {
          quality = 0;
          view.classList.add("of3d-off");
        }
        for (let i = 0; i < slides.length; i++) {
          slides[i].style.setProperty("--of-c", "0");
          slides[i].style.setProperty("--of-rx", "0deg");
          slides[i].style.setProperty("--of-ry", "0deg");
          slides[i].style.setProperty("--of-sheen", "0");
        }
        active = null;
      }

      window.addEventListener("mousemove", onPointer, { passive: true });
      view.addEventListener("mouseleave", onLeave, { passive: true });
      window.addEventListener("touchstart", onLeave, { passive: true });
      window.addEventListener("deviceorientation", onOrient, { passive: true });
      view.classList.add("of3d-on");
      view.classList.remove("of3d-off");
      lastTs = 0;
      fpsFrames = 0;
      fpsSum = 0;
      rafId = window.requestAnimationFrame(frame);

      return function () {
        running = false;
        if (rafId) window.cancelAnimationFrame(rafId);
        window.removeEventListener("mousemove", onPointer);
        view.removeEventListener("mouseleave", onLeave);
        window.removeEventListener("touchstart", onLeave);
        window.removeEventListener("deviceorientation", onOrient);
        view.classList.remove("of3d-on");
        view.classList.remove("of3d-off");
        for (let i = 0; i < slides.length; i++) {
          slides[i].style.removeProperty("--of-c");
          slides[i].style.removeProperty("--of-rx");
          slides[i].style.removeProperty("--of-ry");
          slides[i].style.removeProperty("--of-mx");
          slides[i].style.removeProperty("--of-my");
          slides[i].style.removeProperty("--of-sheen");
        }
      };
    },
    [count]
  );
}
