/* الدول وشركات الشحن — بطاقة لكل دولة، بلا صور */
import "./Skeletons.css";

export default function CarrierSkeleton(props) {
  const count = Math.max(1, Math.min(6, Number(props.count) || 3));
  const items = [];
  for (let i = 0; i < count; i++) {
    items.push(
      <div className="sk-carrier" key={i} aria-hidden="true">
        <div className="sk-row">
          <span className="sk-block sk-circle sk-avatar" />
          <span className="sk-block sk-line" style={{ width: "40%" }} />
        </div>
        <span className="sk-block sk-line" />
        <span className="sk-block sk-line short" />
      </div>
    );
  }
  return (
    <div role="status" aria-live="polite" aria-label="جارٍ تحميل شركات الشحن">
      {items}
    </div>
  );
}
